"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";

export interface FileDropProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onDrop" | "title"> {
  /** Toegestane types, bv. ".pdf,.png" of "image/*". */
  accept?: string;
  multiple?: boolean;
  disabled?: boolean;
  /** Wordt aangeroepen met de gekozen of gesleepte bestanden. */
  onFiles?: (files: File[]) => void;
  title?: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
}

/** FileDrop — sleepzone met bestandskiezer. */
export const FileDrop = React.forwardRef<HTMLDivElement, FileDropProps>(function FileDrop(
  {
    accept,
    multiple,
    disabled,
    onFiles,
    title = "Sleep bestanden hierheen",
    description = "of klik om te bladeren",
    icon,
    className,
    children,
    ...rest
  },
  ref
) {
  const [dragging, setDragging] = React.useState(false);
  const inputRef = React.useRef<HTMLInputElement>(null);

  const handle = (files: FileList | null) => {
    if (!files || files.length === 0) return;
    onFiles?.(Array.from(files));
  };

  return (
    <div
      ref={ref}
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      className={cn("pxui-filedrop", dragging && "pxui-filedrop-dragging", disabled && "pxui-filedrop-disabled", className)}
      onClick={() => !disabled && inputRef.current?.click()}
      onKeyDown={(event) => {
        if (disabled) return;
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          inputRef.current?.click();
        }
      }}
      onDragOver={(event) => {
        event.preventDefault();
        if (!disabled) setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={(event) => {
        event.preventDefault();
        setDragging(false);
        if (!disabled) handle(event.dataTransfer.files);
      }}
      {...rest}
    >
      <input
        ref={inputRef}
        type="file"
        className="pxui-sr-only"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        onChange={(event) => handle(event.target.files)}
      />
      <span className="pxui-filedrop-icon">{icon ?? <Icon name="upload" size={24} />}</span>
      <span className="pxui-filedrop-title">{title}</span>
      {description && <span className="pxui-filedrop-description">{description}</span>}
      {children}
    </div>
  );
});

export interface FileItemProps extends React.HTMLAttributes<HTMLDivElement> {
  name: string;
  size?: number;
  /** Uploadvoortgang 0–100; laat weg als het bestand klaar is. */
  progress?: number;
  onRemove?: () => void;
  icon?: React.ReactNode;
}

/** FileItem — regel met bestandsnaam, grootte en verwijderknop. */
export const FileItem = React.forwardRef<HTMLDivElement, FileItemProps>(function FileItem(
  { name, size, progress, onRemove, icon, className, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-fileitem", className)} {...rest}>
      <span className="pxui-fileitem-icon">{icon ?? <Icon name="file" size={17} />}</span>
      <div className="pxui-fileitem-body">
        <span className="pxui-fileitem-name">{name}</span>
        {size !== undefined && <span className="pxui-fileitem-size">{formatBytes(size)}</span>}
        {progress !== undefined && progress < 100 && (
          <span className="pxui-fileitem-progress">
            <span className="pxui-fileitem-progress-bar" style={{ width: `${progress}%` }} />
          </span>
        )}
      </div>
      {onRemove && (
        <button type="button" className="pxui-fileitem-remove" aria-label={`${name} verwijderen`} onClick={onRemove}>
          <Icon name="x" size={15} />
        </button>
      )}
    </div>
  );
});

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} kB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/* ============================ FileDrop ============================ */
.pxui-filedrop {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 48px 24px; text-align: center; cursor: pointer; user-select: none;
  background: var(--surface); border: 2px dashed var(--border);
  border-radius: var(--r-lg);
  transition: border-color var(--dur), background var(--dur), color var(--dur);
}
.pxui-filedrop:hover, .pxui-filedrop-dragging { border-color: var(--accent); background: var(--accent-tint); }
.pxui-filedrop:focus-visible { outline: none; box-shadow: var(--ring); border-color: var(--accent); }
.pxui-filedrop-disabled { opacity: .55; cursor: not-allowed; }

.pxui-filedrop-icon {
  display: grid; place-items: center; width: 60px; height: 60px;
  border-radius: var(--r-lg); background: var(--surface-2);
  border: 1px solid var(--border); color: var(--accent); margin-bottom: 8px;
  transition: background var(--dur), border-color var(--dur);
}
.pxui-filedrop:hover .pxui-filedrop-icon, .pxui-filedrop-dragging .pxui-filedrop-icon {
  background: color-mix(in srgb, var(--accent) 16%, transparent); border-color: var(--accent);
}
.pxui-filedrop-title { font-size: 14.5px; font-weight: 600; color: var(--text); }
.pxui-filedrop-description { font-size: 13px; color: var(--text-3); }

/* ---------- FileItem ---------- */
.pxui-fileitem {
  display: flex; align-items: center; gap: 12px;
  padding: 11px 13px; background: var(--surface);
  border: 1px solid var(--border); border-radius: var(--r-md);
}
.pxui-fileitem-icon {
  display: grid; place-items: center; width: 32px; height: 32px; flex: none;
  border-radius: var(--r-sm); background: var(--surface-3); color: var(--text-3);
}
.pxui-fileitem-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.pxui-fileitem-name {
  font-size: 13.5px; font-weight: 550; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-fileitem-size { font-size: var(--fs-sm); color: var(--text-3); }
.pxui-fileitem-progress {
  display: block; height: 4px; margin-top: 4px;
  background: var(--surface-3); border-radius: var(--r-full); overflow: hidden;
}
.pxui-fileitem-progress-bar {
  display: block; height: 100%; background: var(--accent);
  border-radius: inherit; transition: width .3s var(--ease-out);
}
.pxui-fileitem-remove {
  flex: none; display: grid; place-items: center; width: 28px; height: 28px;
  border: none; background: transparent; color: var(--text-3);
  border-radius: var(--r-xs); cursor: pointer;
}
.pxui-fileitem-remove:hover { background: var(--red-tint); color: var(--red); }
